import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "content-type",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
};

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_ANON_KEY") || Deno.env.get("SUPABASE_PUBLISHABLE_KEY")!
);

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  try {
    if (req.method === "GET") {
      const clientKey = new URL(req.url).searchParams.get("client_key");
      if (!clientKey) return Response.json({ error: "client_key required" }, { status: 400, headers: cors });
      const { data, error } = await supabase.from("sandbox_runs").select("*").eq("client_key", clientKey).order("updated_at", { ascending: false }).limit(1).maybeSingle();
      if (error) throw error;
      return Response.json({ data }, { headers: cors });
    }
    const body = await req.json();
    if (body.op === "create") {
      const { data, error } = await supabase.from("sandbox_runs").insert({ client_key: body.client_key, status: "ready", state: { source: "sandbox", chain: ["商业博弈 Agent", "策略回测", "风险控制器", "学习记忆"] } }).select().single();
      if (error) throw error;
      return Response.json({ data }, { headers: cors });
    }
    if (body.op === "update") {
      const patch = body.patch || {};
      patch.updated_at = new Date().toISOString();
      const { data, error } = await supabase.from("sandbox_runs").update(patch).eq("id", body.id).select().single();
      if (error) throw error;
      if (body.event) {
        const e = body.event;
        const { error: eventError } = await supabase.from("sandbox_events").insert({ run_id: body.id, event_type: e.type, title: e.title, detail: e.detail || "", payload: e.payload || {} });
        if (eventError) throw eventError;
      }
      return Response.json({ data }, { headers: cors });
    }
    return Response.json({ error: "unsupported operation" }, { status: 400, headers: cors });
  } catch (error) {
    return Response.json({ error: String(error) }, { status: 500, headers: cors });
  }
});
